-- ---------------------------------------------------------------------------
-- 4. Category listing-type settings (IDs, slugs, names, parents unchanged)
-- ---------------------------------------------------------------------------
-- listing_types: which types a category ACCEPTS. Every category, including
-- unconfigured and seller-created ones, accepts both. Narrowing it is an
-- explicit admin decision and is refused if it would strand published
-- listings (guard below).
-- suggested_listing_type: only pre-selects the seller form. Never blocks.
alter table public.catalogue_categories
  add column if not exists listing_types text[] not null default array['product','service']::text[],
  add column if not exists suggested_listing_type text;

do $$
begin
  if not exists (select 1 from pg_constraint
                 where conname = 'catalogue_categories_listing_types_check'
                   and conrelid = 'public.catalogue_categories'::regclass) then
    alter table public.catalogue_categories
      add constraint catalogue_categories_listing_types_check
      check (cardinality(listing_types) between 1 and 2
             and listing_types <@ array['product','service']::text[]);
  end if;

  if not exists (select 1 from pg_constraint
                 where conname = 'catalogue_categories_suggested_listing_type_check'
                   and conrelid = 'public.catalogue_categories'::regclass) then
    alter table public.catalogue_categories
      add constraint catalogue_categories_suggested_listing_type_check
      check (suggested_listing_type is null or suggested_listing_type in ('product','service'));
  end if;
end $$;

-- Form guidance seeded from the labelled Products / Services sections. Only
-- unset rows are touched, so admin edits survive a rerun.
update public.catalogue_categories
set suggested_listing_type = 'service'
where suggested_listing_type is null
  and slug in (
    -- Food & Grocery: Culinary & Catering Services
    'private-chefs-cooks','event-catering-services','catering','home-cooked-meals',
    'cakes-pastries-baking','outdoor-catering-bbq','meal-prep-subscriptions',
    'culinary-training-classes','bartending-beverage-services',
    'food-decoration-presentation','restaurant-kitchen-consulting',
    -- Professional Services: Business, Creative & Tech
    'business-services','graphic-design','web-development','app-development',
    'ai-automation-services','marketing-advertising','social-media-services',
    'photography-services','video-production','music-audio-services',
    'writing-editing','consulting','accounting-finance-services','education-tutoring',
    -- Professional Services: Legal Advice & Services
    'legal-services','business-corporate-law','property-real-estate-law',
    'family-matrimonial-law','criminal-defense-litigation','immigration-visa-law',
    'intellectual-property-law','employment-labour-law','contract-drafting-review',
    'tax-financial-law','dispute-resolution-mediation','wills-probate-estate',
    -- Construction: Property Improvement & Maintenance
    'building-renovation','pop-screeding-finishing','waterproofing-damp-control',
    'landscaping-exterior','building-maintenance-handyman',
    -- Construction: Technical & Professional Services
    'architectural-design','civil-structural-engineering','quantity-surveying',
    'land-surveying-site-prep','building-inspection-supervision',
    -- Artisans, Technicians & Repairs
    'appliance-repairs','phone-tablet-repairs','computer-laptop-repairs',
    'electronics-repairs','generator-repairs','solar-inverter-technicians',
    'electrical-repairs','plumbing-pipe-repairs','ac-refrigeration-repairs',
    'borehole-pump-technicians','cctv-security-technicians',
    'automotive-mechanics','auto-electricians-diagnostics','motorcycle-tricycle-repairs',
    'welding-metal-fabrication','carpentry-furniture-repairs','painting-decorating',
    'tiling-flooring','pop-ceiling-installation','locksmith-key-cutting',
    'upholstery-restoration','tailoring-alterations','shoe-making-repairs',
    'cleaning-maintenance-services','general-handyman'
  );

update public.catalogue_categories
set suggested_listing_type = 'product'
where suggested_listing_type is null
  and slug in (
    'food-groceries','drinks-beverages','snacks-confectionery','baked-goods',
    'farm-produce','meat-seafood'
  );

-- ---------------------------------------------------------------------------
-- 5. Listing columns on catalogue_items (defaults = today's behaviour)
-- ---------------------------------------------------------------------------
-- Every existing row becomes product + fixed, exactly how checkout already
-- treats it. Ambiguous rows are flagged (section 9), never reclassified.
alter table public.catalogue_items
  add column if not exists listing_type text not null default 'product',
  add column if not exists pricing_model text not null default 'fixed',
  add column if not exists price_unit text,
  -- Services only: what the price includes, and where/when/how it is
  -- delivered. Required (with confirmation) before a service is published.
  add column if not exists service_scope text,
  add column if not exists service_terms text,
  add column if not exists service_scope_confirmed boolean not null default false,
  add column if not exists needs_type_review boolean not null default false,
  add column if not exists type_review_reason text,
  add column if not exists type_reviewed_at timestamptz;

do $$
begin
  if not exists (select 1 from pg_constraint
                 where conname = 'catalogue_items_listing_type_check'
                   and conrelid = 'public.catalogue_items'::regclass) then
    alter table public.catalogue_items
      add constraint catalogue_items_listing_type_check
      check (listing_type in ('product','service'));
  end if;

  if not exists (select 1 from pg_constraint
                 where conname = 'catalogue_items_pricing_model_fkey'
                   and conrelid = 'public.catalogue_items'::regclass) then
    alter table public.catalogue_items
      add constraint catalogue_items_pricing_model_fkey
      foreign key (pricing_model) references public.catalogue_pricing_models(key);
  end if;

  if not exists (select 1 from pg_constraint
                 where conname = 'catalogue_items_price_unit_check'
                   and conrelid = 'public.catalogue_items'::regclass) then
    alter table public.catalogue_items
      add constraint catalogue_items_price_unit_check
      check (price_unit is null or char_length(btrim(price_unit)) between 1 and 30);
  end if;

  if not exists (select 1 from pg_constraint
                 where conname = 'catalogue_items_service_text_check'
                   and conrelid = 'public.catalogue_items'::regclass) then
    alter table public.catalogue_items
      add constraint catalogue_items_service_text_check
      check ((service_scope is null or char_length(btrim(service_scope)) between 20 and 2000)
         and (service_terms is null or char_length(btrim(service_terms)) between 10 and 1000));
  end if;

  -- Data integrity only: this limits the stored values to the three the apps
  -- use. It does NOT stop checkout accepting a paused listing - the payment
  -- endpoints treat every non-deleted listing as purchasable (see
  -- docs/PAYMENT_SECURITY_FINDINGS.md, item 3). Existing rows were verified
  -- in section 0, so the constraint is added fully validated.
  if not exists (select 1 from pg_constraint
                 where conname = 'catalogue_items_status_check'
                   and conrelid = 'public.catalogue_items'::regclass) then
    alter table public.catalogue_items
      add constraint catalogue_items_status_check
      check (status is not null and status in ('active', 'paused', 'deleted'));
  end if;
end $$;

create index if not exists catalogue_items_listing_type_idx
  on public.catalogue_items(listing_type);
create index if not exists catalogue_items_pricing_model_idx
  on public.catalogue_items(pricing_model);
create index if not exists catalogue_items_needs_type_review_idx
  on public.catalogue_items(seller_username) where needs_type_review;

-- ---------------------------------------------------------------------------
-- 6. Product and service details (informational display metadata only)
-- ---------------------------------------------------------------------------
-- No stock or availability fields here: checkout cannot reserve inventory
-- or check availability, so published listings make no such claim. Stock,
-- preorder and made-to-order configurations live in drafts.
create table if not exists public.catalogue_product_details (
  item_id uuid primary key references public.catalogue_items(id) on delete cascade,
  condition text check (condition in ('new','used_like_new','used_good','used_fair','refurbished','not_applicable')),
  brand text check (brand is null or char_length(btrim(brand)) between 1 and 80),
  sku text check (sku is null or char_length(btrim(sku)) between 1 and 60),
  fulfillment_methods text[] not null default '{}'::text[]
    check (fulfillment_methods <@ array['delivery','pickup','shipping','digital_delivery']::text[]),
  delivery_areas text check (delivery_areas is null or char_length(delivery_areas) <= 300),
  -- Seller's estimate; shown as an estimate, not enforced.
  estimated_dispatch_days integer check (estimated_dispatch_days is null or estimated_dispatch_days between 0 and 365),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.catalogue_service_details (
  item_id uuid primary key references public.catalogue_items(id) on delete cascade,
  service_modes text[] not null default '{}'::text[]
    check (service_modes <@ array['on_site','at_provider','remote']::text[]),
  service_area text check (service_area is null or char_length(service_area) <= 300),
  typical_duration_minutes integer check (typical_duration_minutes is null or typical_duration_minutes between 1 and 100000),
  experience_years integer check (experience_years is null or experience_years between 0 and 80),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- 7. Configurable category attributes
-- ---------------------------------------------------------------------------
-- category_id null = every category; listing_type null = both types.
-- Unconfigured categories have no rows and fall back to standard fields.
create table if not exists public.catalogue_attribute_definitions (
  id uuid primary key default gen_random_uuid(),
  category_id uuid references public.catalogue_categories(id) on delete cascade,
  listing_type text check (listing_type in ('product','service')),
  key text not null check (key ~ '^[a-z][a-z0-9_]{1,39}$'),
  label text not null check (char_length(btrim(label)) between 1 and 60),
  input_type text not null check (input_type in ('text','number','select','multi_select','boolean')),
  options jsonb not null default '[]'::jsonb check (jsonb_typeof(options) = 'array'),
  unit text check (unit is null or char_length(btrim(unit)) between 1 and 30),
  is_required boolean not null default false,
  allow_other boolean not null default true,
  min_number numeric,
  max_number numeric,
  sort_order integer not null default 100,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  check (min_number is null or max_number is null or min_number <= max_number)
);

create unique index if not exists catalogue_attribute_definitions_scope_key_unique
  on public.catalogue_attribute_definitions (
    coalesce(category_id, '00000000-0000-0000-0000-000000000000'::uuid),
    coalesce(listing_type, 'any'),
    key
  );

create table if not exists public.catalogue_item_attributes (
  id uuid primary key default gen_random_uuid(),
  item_id uuid not null references public.catalogue_items(id) on delete cascade,
  attribute_id uuid references public.catalogue_attribute_definitions(id) on delete set null,
  -- "Other / Specify": seller-defined attribute with its own label
  custom_label text check (custom_label is null or char_length(btrim(custom_label)) between 1 and 60),
  value jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (attribute_id is not null or custom_label is not null)
);

create unique index if not exists catalogue_item_attributes_defined_unique
  on public.catalogue_item_attributes (item_id, attribute_id)
  where attribute_id is not null;
create unique index if not exists catalogue_item_attributes_custom_unique
  on public.catalogue_item_attributes (item_id, lower(btrim(custom_label)))
  where custom_label is not null;

-- ---------------------------------------------------------------------------
-- 8. Drafts (private; never read by checkout)
-- ---------------------------------------------------------------------------
create table if not exists public.catalogue_listing_drafts (
  id uuid primary key default gen_random_uuid(),
  seller_username text not null,
  listing_type text not null check (listing_type in ('product','service')),
  category_id uuid references public.catalogue_categories(id) on delete set null,
  title text not null check (char_length(btrim(title)) between 1 and 120),
  description text check (description is null or char_length(description) <= 5000),
  pricing_model text not null references public.catalogue_pricing_models(key),
  price_usd numeric check (price_usd is null or (price_usd <> 'NaN'::numeric
                                                 and price_usd::text not in ('Infinity','-Infinity')
                                                 and price_usd > 0)),
  price_max_usd numeric check (price_max_usd is null or (price_max_usd <> 'NaN'::numeric
                                                         and price_max_usd::text not in ('Infinity','-Infinity')
                                                         and price_max_usd > 0)),
  price_unit text check (price_unit is null or char_length(btrim(price_unit)) between 1 and 30),
  min_order_qty integer check (min_order_qty is null or min_order_qty >= 1),
  max_order_qty integer check (max_order_qty is null or max_order_qty >= 1),
  stock_status text check (stock_status in ('in_stock','limited','made_to_order','preorder','out_of_stock')),
  stock_quantity integer check (stock_quantity is null or stock_quantity >= 0),
  service_scope text check (service_scope is null or char_length(service_scope) <= 2000),
  service_terms text check (service_terms is null or char_length(service_terms) <= 1000),
  product_details jsonb not null default '{}'::jsonb check (jsonb_typeof(product_details) = 'object'),
  service_details jsonb not null default '{}'::jsonb check (jsonb_typeof(service_details) = 'object'),
  attributes jsonb not null default '[]'::jsonb check (jsonb_typeof(attributes) = 'array'),
  pricing_options jsonb not null default '[]'::jsonb check (jsonb_typeof(pricing_options) = 'array'),
  images jsonb not null default '[]'::jsonb check (jsonb_typeof(images) = 'array'),
  promo_video_url text,
  blocking_reasons text[] not null default '{}'::text[],
  -- Set when the API publishes a checkout-compatible draft; the published
  -- row is then governed by the catalogue_items rules.
  published_item_id uuid references public.catalogue_items(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (price_max_usd is null or price_usd is null or price_max_usd >= price_usd),
  check (max_order_qty is null or min_order_qty is null or max_order_qty >= min_order_qty)
);

create index if not exists catalogue_listing_drafts_seller_idx
  on public.catalogue_listing_drafts(seller_username, updated_at desc);

-- Pricing-model guard needs the drafts table, so it is attached here.
drop trigger if exists catalogue_pricing_models_guard on public.catalogue_pricing_models;
create trigger catalogue_pricing_models_guard
  before insert or update or delete on public.catalogue_pricing_models
  for each row execute function public.catalogue_pricing_models_guard();

-- Draft ownership, enforced by the database for every role (the future
-- drafts API must also check the logged-in seller; this is the backstop).
-- 1) a draft can only link to a listing owned by the same seller;
-- 2) a listing's seller cannot be changed while a draft of another seller
--    is linked to it, so the relationship cannot become invalid later.
create index if not exists catalogue_listing_drafts_published_item_idx
  on public.catalogue_listing_drafts(published_item_id)
  where published_item_id is not null;

create or replace function public.catalogue_listing_drafts_owner_guard()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
declare
  item_seller text;
begin
  if new.published_item_id is null then
    return new;
  end if;

  -- FOR SHARE: a concurrent seller change on this listing must wait for this
  -- draft to commit (and is then rejected by the listing guard below), or, if
  -- it committed first, this statement reads the new seller.
  select seller_username into item_seller
  from public.catalogue_items where id = new.published_item_id
  for share;

  if not found then
    raise exception using errcode = '23503',
      message = 'The published listing does not exist.';
  end if;

  if item_seller is distinct from new.seller_username then
    raise exception using errcode = '42501',
      message = 'A draft can only be linked to a listing owned by the same seller.';
  end if;

  return new;
end;
$$;

drop trigger if exists catalogue_listing_drafts_owner_guard on public.catalogue_listing_drafts;
create trigger catalogue_listing_drafts_owner_guard
  before insert or update of published_item_id, seller_username on public.catalogue_listing_drafts
  for each row execute function public.catalogue_listing_drafts_owner_guard();

create or replace function public.catalogue_items_seller_change_guard()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
declare
  linked integer;
begin
  -- Take the listing's row lock first. If a draft is being linked concurrently
  -- this waits for it to commit, and the count below (a new snapshot) then sees it.
  perform 1 from public.catalogue_items where id = new.id for update;

  select count(*) into linked
  from public.catalogue_listing_drafts d
  where d.published_item_id = new.id
    and d.seller_username is distinct from new.seller_username;

  if linked > 0 then
    raise exception using errcode = '42501',
      message = format('%s linked draft(s) belong to a different seller. Unlink them before changing this listing''s seller.', linked);
  end if;
  return new;
end;
$$;

drop trigger if exists catalogue_items_seller_change_guard on public.catalogue_items;
create trigger catalogue_items_seller_change_guard
  before update of seller_username on public.catalogue_items
  for each row
  when (old.seller_username is distinct from new.seller_username)
  execute function public.catalogue_items_seller_change_guard();

-- ---------------------------------------------------------------------------
-- 9. Flag ambiguous legacy listings for seller review (no reclassification)
-- ---------------------------------------------------------------------------
-- Only listings in categories suggested as product-only are unambiguous.
-- type_reviewed_at keeps a rerun from re-flagging confirmed listings.
-- Not in the listings trigger's column list, so this update runs no checks.
update public.catalogue_items i
set needs_type_review = true,
    type_review_reason = case
      when c.slug = 'other' then 'category_other'
      when c.suggested_listing_type = 'service' then 'category_suggests_service'
      else 'category_mixed'
    end
from public.catalogue_categories c
where c.id = i.category_id
  and i.status is distinct from 'deleted'
  and i.needs_type_review = false
  and i.type_reviewed_at is null
  and (c.slug = 'other' or c.suggested_listing_type is distinct from 'product');

-- ---------------------------------------------------------------------------
-- 10. Write-time guards
-- ---------------------------------------------------------------------------
-- Listings. Only the listings API and (until replaced) the website dashboard
-- write catalogue_items; payment code only reads it.
-- Full validation runs on insert, on ANY status change to a non-deleted
-- status (so paused -> active re-checks a legacy invalid price), and when
-- any purchase-relevant field changes. Title/description/image edits and
-- soft deletion run no checks.
-- Security definer so the checks read the configuration tables the same way
-- regardless of which role performs the write.
create or replace function public.catalogue_items_enforce_listing_rules()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
declare
  model public.catalogue_pricing_models%rowtype;
  category_types text[];
begin
  if new.status is not distinct from 'deleted' then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and new.status is not distinct from old.status
     and new.price_usd is not distinct from old.price_usd
     and new.listing_type is not distinct from old.listing_type
     and new.pricing_model is not distinct from old.pricing_model
     and new.price_unit is not distinct from old.price_unit
     and new.category_id is not distinct from old.category_id
     and new.service_scope is not distinct from old.service_scope
     and new.service_terms is not distinct from old.service_terms
     and new.service_scope_confirmed is not distinct from old.service_scope_confirmed then
    return new;
  end if;

  if new.price_usd is null
     or new.price_usd = 'NaN'::numeric
     or new.price_usd::text in ('Infinity', '-Infinity')
     or new.price_usd <= 0 then
    raise exception using errcode = '23514',
      message = 'Listing price must be a positive USD amount.';
  end if;

  select * into model from public.catalogue_pricing_models where key = new.pricing_model;
  if not found or not model.is_active or not (new.listing_type = any(model.applies_to)) then
    raise exception using errcode = '23514',
      message = 'This pricing model is not available for this listing type.';
  end if;
  if not model.checkout_compatible then
    raise exception using errcode = '23514',
      message = 'This pricing model cannot be published yet. Save it as a draft.';
  end if;
  if model.requires_unit and (new.price_unit is null or btrim(new.price_unit) = '') then
    raise exception using errcode = '23514',
      message = 'This pricing model needs a unit.';
  end if;

  if new.listing_type = 'service'
     and (new.service_scope is null
          or new.service_terms is null
          or not new.service_scope_confirmed) then
    raise exception using errcode = '23514',
      message = 'A service can only be published with a defined scope and terms that the seller confirms are the complete offering. Otherwise save it as a draft.';
  end if;

  select listing_types into category_types
  from public.catalogue_categories where id = new.category_id;
  if category_types is not null and not (new.listing_type = any(category_types)) then
    raise exception using errcode = '23514',
      message = 'This category does not accept this listing type.';
  end if;

  return new;
end;
$$;

drop trigger if exists catalogue_items_enforce_listing_rules on public.catalogue_items;
create trigger catalogue_items_enforce_listing_rules
  before insert or update of price_usd, status, listing_type, pricing_model, price_unit,
                             category_id, service_scope, service_terms, service_scope_confirmed
  on public.catalogue_items
  for each row execute function public.catalogue_items_enforce_listing_rules();

-- Categories: narrowing listing_types must not strand published listings.
create or replace function public.catalogue_categories_listing_types_guard()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
declare
  stranded integer;
begin
  select count(*) into stranded
  from public.catalogue_items
  where category_id = new.id
    and status is distinct from 'deleted'
    and not (listing_type = any(new.listing_types));
  if stranded > 0 then
    raise exception using errcode = '23514',
      message = format('%s published listing(s) in this category use a listing type it would no longer accept.', stranded);
  end if;
  return new;
end;
$$;

drop trigger if exists catalogue_categories_listing_types_guard on public.catalogue_categories;
create trigger catalogue_categories_listing_types_guard
  before update of listing_types on public.catalogue_categories
  for each row
  when (old.listing_types is distinct from new.listing_types)
  execute function public.catalogue_categories_listing_types_guard();

-- ---------------------------------------------------------------------------
-- 11. Functions, row-level security and grants for the new objects
-- ---------------------------------------------------------------------------
-- Writes go through the server API (service role) only. catalogue_items'
-- own policies and grants are NOT changed here.
--
-- Supabase grants new tables and functions to anon, authenticated and
-- service_role by default, and functions to PUBLIC. Everything below removes
-- what is not needed; section 12 then verifies the effective result and
-- aborts the whole migration if it is wrong.

-- Remove objects from an earlier draft of this migration, if any exist.
drop function if exists public.catalogue_item_is_public(uuid);
drop function if exists public.catalogue_set_checkout_compatible(text, boolean, text, text);

-- Functions: closed to PUBLIC and to every API role. Trigger functions need no
-- EXECUTE privilege to fire. Only the owner/superusers can call the approval
-- function, and it refuses anyone else (section 2).
revoke all on function public.catalogue_checkout_approvals_set_identity() from public, anon, authenticated, service_role;
revoke all on function public.catalogue_checkout_approvals_append_only() from public, anon, authenticated, service_role;
revoke all on function public.catalogue_pricing_models_guard() from public, anon, authenticated, service_role;
revoke all on function public.catalogue_set_checkout_compatible(text, boolean, text) from public, anon, authenticated, service_role;
revoke all on function public.catalogue_items_enforce_listing_rules() from public, anon, authenticated, service_role;
revoke all on function public.catalogue_categories_listing_types_guard() from public, anon, authenticated, service_role;
revoke all on function public.catalogue_listing_drafts_owner_guard() from public, anon, authenticated, service_role;
revoke all on function public.catalogue_items_seller_change_guard() from public, anon, authenticated, service_role;

alter table public.catalogue_pricing_models enable row level security;
alter table public.catalogue_checkout_model_approvals enable row level security;
alter table public.catalogue_units enable row level security;
alter table public.catalogue_attribute_definitions enable row level security;
alter table public.catalogue_product_details enable row level security;
alter table public.catalogue_service_details enable row level security;
alter table public.catalogue_item_attributes enable row level security;
alter table public.catalogue_listing_drafts enable row level security;

-- Public roles: read-only on configuration and details, nothing on drafts or
-- approvals. Explicit so it does not depend on default privileges.
revoke all on public.catalogue_pricing_models, public.catalogue_units,
     public.catalogue_attribute_definitions, public.catalogue_product_details,
     public.catalogue_service_details, public.catalogue_item_attributes
  from anon, authenticated;
grant select on public.catalogue_pricing_models, public.catalogue_units,
     public.catalogue_attribute_definitions, public.catalogue_product_details,
     public.catalogue_service_details, public.catalogue_item_attributes
  to anon, authenticated;
revoke all on public.catalogue_listing_drafts from anon, authenticated;
revoke all on public.catalogue_checkout_model_approvals from anon, authenticated;

-- service_role (the server API key):
--   * pricing models: read only. Changing them is the database owner's job.
--   * approval records and their sequence: no access at all.
--   * units, attribute definitions, drafts, details, item attributes: normal
--     data access for the API, but never TRUNCATE, REFERENCES or TRIGGER.
revoke all on public.catalogue_checkout_model_approvals from service_role;
revoke all on sequence public.catalogue_checkout_model_approvals_id_seq from anon, authenticated, service_role;
revoke all on public.catalogue_pricing_models from service_role;
grant select on public.catalogue_pricing_models to service_role;
revoke all on public.catalogue_units, public.catalogue_attribute_definitions,
     public.catalogue_product_details, public.catalogue_service_details,
     public.catalogue_item_attributes, public.catalogue_listing_drafts
  from service_role;
grant select, insert, update, delete on public.catalogue_units,
     public.catalogue_attribute_definitions, public.catalogue_product_details,
     public.catalogue_service_details, public.catalogue_item_attributes,
     public.catalogue_listing_drafts
  to service_role;

drop policy if exists catalogue_pricing_models_public_read on public.catalogue_pricing_models;
create policy catalogue_pricing_models_public_read on public.catalogue_pricing_models
  for select to anon, authenticated using (is_active);

drop policy if exists catalogue_units_public_read on public.catalogue_units;
create policy catalogue_units_public_read on public.catalogue_units
  for select to anon, authenticated using (is_active);

drop policy if exists catalogue_attribute_definitions_public_read on public.catalogue_attribute_definitions;
create policy catalogue_attribute_definitions_public_read on public.catalogue_attribute_definitions
  for select to anon, authenticated using (is_active);

-- Details are readable exactly when the listing itself is readable by the
-- caller. The sub-select is evaluated with the caller's own privileges and
-- catalogue_items' own row-level security, so the existing listing read
-- policy (currently "status <> 'deleted'") is followed automatically, with
-- no copy of that rule here and no change to that policy.
drop policy if exists catalogue_product_details_public_read on public.catalogue_product_details;
create policy catalogue_product_details_public_read on public.catalogue_product_details
  for select to anon, authenticated
  using (exists (select 1 from public.catalogue_items i where i.id = catalogue_product_details.item_id));

drop policy if exists catalogue_service_details_public_read on public.catalogue_service_details;
create policy catalogue_service_details_public_read on public.catalogue_service_details
  for select to anon, authenticated
  using (exists (select 1 from public.catalogue_items i where i.id = catalogue_service_details.item_id));

drop policy if exists catalogue_item_attributes_public_read on public.catalogue_item_attributes;
create policy catalogue_item_attributes_public_read on public.catalogue_item_attributes
  for select to anon, authenticated
  using (exists (select 1 from public.catalogue_items i where i.id = catalogue_item_attributes.item_id));

-- catalogue_listing_drafts and catalogue_checkout_model_approvals: RLS on, no
-- policies, no grants to public roles -> drafts are server API only; approval
-- records are owner only.

-- ---------------------------------------------------------------------------
-- 12. Post-checks (abort the whole migration if anything is wrong)
-- ---------------------------------------------------------------------------
do $$
declare
  flagged integer;
  compatible text;
  unsupported integer;
  unaudited text;
  problems text[] := '{}';
  fn text;
  fn_oid regprocedure;
  r text;
  t text;
  p text;
  all_new constant text[] := array[
    'catalogue_pricing_models','catalogue_checkout_model_approvals','catalogue_units',
    'catalogue_attribute_definitions','catalogue_product_details','catalogue_service_details',
    'catalogue_item_attributes','catalogue_listing_drafts'];
  write_privs constant text[] := array['INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'];
begin
  select count(*) into flagged from public.catalogue_items where needs_type_review;
  select string_agg(key, ', ' order by sort_order) into compatible
  from public.catalogue_pricing_models where checkout_compatible;
  select count(*) into unsupported
  from public.catalogue_items i
  join public.catalogue_pricing_models m on m.key = i.pricing_model
  where i.status is distinct from 'deleted' and not m.checkout_compatible;
  if unsupported > 0 then
    raise exception 'Unexpected: % published listing(s) on a non-checkout-compatible model', unsupported;
  end if;

  select string_agg(m.key, ', ') into unaudited
  from public.catalogue_pricing_models m
  where m.checkout_compatible
    and not exists (select 1 from public.catalogue_checkout_model_approvals a
                    where a.pricing_model = m.key and a.approved_value);
  if unaudited is not null then
    raise exception 'Checkout-compatible model(s) without an approval record: %', unaudited;
  end if;

  -- Functions: not executable by PUBLIC or any API role.
  foreach fn in array array[
    'public.catalogue_checkout_approvals_set_identity()',
    'public.catalogue_checkout_approvals_append_only()',
    'public.catalogue_pricing_models_guard()',
    'public.catalogue_set_checkout_compatible(text, boolean, text)',
    'public.catalogue_items_enforce_listing_rules()',
    'public.catalogue_categories_listing_types_guard()',
    'public.catalogue_listing_drafts_owner_guard()',
    'public.catalogue_items_seller_change_guard()'] loop
    fn_oid := to_regprocedure(fn);
    if fn_oid is null then
      problems := problems || (fn || ' is missing');
      continue;
    end if;
    if exists (
      select 1
      from pg_proc pr,
           aclexplode(coalesce(pr.proacl, acldefault('f', pr.proowner))) a
      where pr.oid = fn_oid and a.grantee = 0 and a.privilege_type = 'EXECUTE'
    ) then
      problems := problems || (fn || ' is executable by PUBLIC');
    end if;
    foreach r in array array['anon','authenticated','service_role'] loop
      if has_function_privilege(r, fn_oid, 'EXECUTE') then
        problems := problems || (fn || ' is executable by ' || r);
      end if;
    end loop;
  end loop;

  -- Tables: no write privileges for the public roles.
  foreach t in array all_new loop
    foreach r in array array['anon','authenticated'] loop
      foreach p in array write_privs loop
        if has_table_privilege(r, 'public.' || t, p) then
          problems := problems || (r || ' has ' || p || ' on ' || t);
        end if;
      end loop;
    end loop;
    if not (select relrowsecurity from pg_class where oid = ('public.' || t)::regclass) then
      problems := problems || ('row-level security is off on ' || t);
    end if;
  end loop;

  foreach t in array array['catalogue_listing_drafts','catalogue_checkout_model_approvals'] loop
    foreach r in array array['anon','authenticated'] loop
      if has_table_privilege(r, 'public.' || t, 'SELECT') then
        problems := problems || (r || ' can read ' || t);
      end if;
    end loop;
  end loop;

  -- service_role: no approval access, no pricing-model writes, no
  -- TRUNCATE/REFERENCES/TRIGGER on the new tables; keeps the data access the API needs.
  foreach p in array array['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] loop
    if has_table_privilege('service_role', 'public.catalogue_checkout_model_approvals', p) then
      problems := problems || ('service_role has ' || p || ' on catalogue_checkout_model_approvals');
    end if;
  end loop;
  foreach r in array array['anon','authenticated','service_role'] loop
    if has_sequence_privilege(r, 'public.catalogue_checkout_model_approvals_id_seq', 'USAGE')
       or has_sequence_privilege(r, 'public.catalogue_checkout_model_approvals_id_seq', 'SELECT')
       or has_sequence_privilege(r, 'public.catalogue_checkout_model_approvals_id_seq', 'UPDATE') then
      problems := problems || (r || ' can use the approvals sequence');
    end if;
  end loop;
  foreach p in array write_privs loop
    if has_table_privilege('service_role', 'public.catalogue_pricing_models', p) then
      problems := problems || ('service_role has ' || p || ' on catalogue_pricing_models');
    end if;
  end loop;
  if not has_table_privilege('service_role', 'public.catalogue_pricing_models', 'SELECT') then
    problems := problems || 'service_role cannot read catalogue_pricing_models';
  end if;
  foreach t in array array['catalogue_units','catalogue_attribute_definitions','catalogue_product_details',
                           'catalogue_service_details','catalogue_item_attributes','catalogue_listing_drafts'] loop
    foreach p in array array['TRUNCATE','REFERENCES','TRIGGER'] loop
      if has_table_privilege('service_role', 'public.' || t, p) then
        problems := problems || ('service_role has ' || p || ' on ' || t);
      end if;
    end loop;
    foreach p in array array['SELECT','INSERT','UPDATE','DELETE'] loop
      if not has_table_privilege('service_role', 'public.' || t, p) then
        problems := problems || ('service_role lacks ' || p || ' on ' || t);
      end if;
    end loop;
  end loop;

  if not has_function_privilege(current_user, 'public.catalogue_set_checkout_compatible(text, boolean, text)'::regprocedure, 'EXECUTE') then
    problems := problems || 'the migration owner cannot execute catalogue_set_checkout_compatible';
  end if;

  if cardinality(problems) > 0 then
    raise exception 'Permission post-check failed (nothing was saved): %', array_to_string(problems, '; ');
  end if;

  raise notice 'Listings flagged for type review: %', flagged;
  raise notice 'Checkout-compatible pricing models: %', compatible;
  raise notice 'Permission post-checks passed';
end $$;

-- (commit; removed by dry-run builder)

-- ===========================================================================
-- Dry run: helpers and checks
-- ===========================================================================
create temp table dry_run_results (
  seq serial primary key,
  ok boolean not null,
  test text not null,
  detail text
);

create temp table dry_run_ctx as
select
  (select id from public.catalogue_categories
   where parent_id is not null and slug <> 'other'
   order by slug limit 1) as category_id,
  (select c.id from public.catalogue_categories c
   where c.parent_id is not null and c.slug <> 'other'
     and not exists (select 1 from public.catalogue_items i where i.category_id = c.id)
   order by c.slug desc limit 1) as empty_category_id,
  (select id from dry_run_items_before
   where status is distinct from 'deleted'
   order by created_at limit 1) as existing_item_id,
  (select seller_username from dry_run_items_before
   where status is distinct from 'deleted'
   order by created_at limit 1) as existing_seller,
  (select pg_get_userbyid(c.relowner)::text from pg_class c
   where c.oid = 'public.catalogue_pricing_models'::regclass) as owner_role;

create function pg_temp.dr_record(p_ok boolean, p_test text, p_detail text)
returns void
language sql
as $f$
  insert into dry_run_results (ok, test, detail) values (p_ok, p_test, p_detail);
$f$;

-- Runs p_sql in a subtransaction that is always undone, and records whether
-- it succeeded or failed as expected.
create function pg_temp.dr_expect(p_test text, p_sql text, p_should_succeed boolean, p_error_like text default null)
returns void
language plpgsql
as $f$
declare
  v_err text;
begin
  begin
    execute p_sql;
    raise exception 'dry_run_undo';
  exception when others then
    v_err := case when sqlerrm = 'dry_run_undo' then null else sqlerrm end;
  end;

  if p_should_succeed then
    perform pg_temp.dr_record(v_err is null, p_test,
      coalesce('UNEXPECTED ERROR: ' || v_err, 'accepted'));
  else
    perform pg_temp.dr_record(
      v_err is not null and (p_error_like is null or v_err ilike '%' || p_error_like || '%'),
      p_test,
      coalesce('rejected: ' || v_err, 'UNEXPECTEDLY ACCEPTED'));
  end if;
end;
$f$;

-- Runs statements in order inside an undone subtransaction and returns the
-- text value of the last one (or the error message).
create function pg_temp.dr_probe(p_stmts text[])
returns text
language plpgsql
as $f$
declare
  v_i integer;
  v_res text;
  v_err text;
begin
  begin
    for v_i in 1 .. cardinality(p_stmts) - 1 loop
      execute p_stmts[v_i];
    end loop;
    execute p_stmts[cardinality(p_stmts)] into v_res;
    raise exception 'dry_run_undo';
  exception when others then
    if sqlerrm <> 'dry_run_undo' then
      v_err := sqlerrm;
    end if;
  end;
  return coalesce('ERROR: ' || v_err, v_res);
end;
$f$;

create function pg_temp.dr_insert(
  p_price text, p_type text, p_model text,
  p_unit text default null, p_scope text default null, p_terms text default null,
  p_confirmed boolean default false, p_category uuid default null,
  p_status text default 'active', p_seller text default 'dry_run_seller'
)
returns text
language sql
as $f$
  select format(
    'insert into public.catalogue_items (id, seller_username, title, price_usd, status, category_id, payment_methods, listing_type, pricing_model, price_unit, service_scope, service_terms, service_scope_confirmed) values (gen_random_uuid(), %L, %L, %s, %L, %L::uuid, %L::jsonb, %L, %L, %L, %L, %L, %L)',
    p_seller, 'Dry run listing', p_price, p_status,
    coalesce(p_category, (select category_id from dry_run_ctx)),
    '["usdt"]', p_type, p_model, p_unit, p_scope, p_terms, p_confirmed)
$f$;

-- ---------------------------------------------------------------------------
-- A. Environment, preservation, repeatability, status data
-- ---------------------------------------------------------------------------
do $a$
declare
  v_ctx record;
  v_pass1 record;
  v_n integer;
  v_txt text;
begin
  select * into v_ctx from dry_run_ctx;
  perform pg_temp.dr_record(v_ctx.category_id is not null and v_ctx.empty_category_id is not null
                            and v_ctx.existing_item_id is not null and v_ctx.owner_role is not null,
    'S00 test fixtures found',
    format('category=%s empty_category=%s existing_item=%s owner_role=%s', v_ctx.category_id, v_ctx.empty_category_id, v_ctx.existing_item_id, v_ctx.owner_role));

  perform pg_temp.dr_record(true, 'INFO running as',
    format('session_user=%s current_user=%s superuser=%s database_owner_role=%s server=%s',
      session_user, current_user, (select rolsuper from pg_roles where rolname = current_user),
      v_ctx.owner_role, current_setting('server_version')));

  perform pg_temp.dr_expect('E01 test session can act as anon', 'do $x$ begin set local role anon; end $x$', true);
  perform pg_temp.dr_expect('E02 test session can act as authenticated', 'do $x$ begin set local role authenticated; end $x$', true);
  perform pg_temp.dr_expect('E03 test session can act as service_role', 'do $x$ begin set local role service_role; end $x$', true);

  select count(*) into v_n from (
    (select * from dry_run_items_before
     except
     select id, seller_username, title, description, price_usd, images, payment_methods,
            status, created_at, updated_at, size, promo_video_url, category_id
     from public.catalogue_items)
    union all
    (select id, seller_username, title, description, price_usd, images, payment_methods,
            status, created_at, updated_at, size, promo_video_url, category_id
     from public.catalogue_items
     except
     select * from dry_run_items_before)
  ) d;
  perform pg_temp.dr_record(v_n = 0, 'S01 existing listings unchanged (ids, prices, status, seller, category, dates)',
    format('%s differing row(s); listings=%s', v_n, (select count(*) from public.catalogue_items)));

  select count(*) into v_n from (
    (select * from dry_run_categories_before
     except select id, slug, name, parent_id from public.catalogue_categories)
    union all
    (select id, slug, name, parent_id from public.catalogue_categories
     except select * from dry_run_categories_before)
  ) d;
  perform pg_temp.dr_record(v_n = 0, 'S02 categories unchanged (ids, slugs, names, parents)',
    format('%s differing row(s); categories=%s', v_n, (select count(*) from public.catalogue_categories)));

  select count(*) into v_n from (
    (select * from dry_run_item_columns_before
     except
     select column_name::text, data_type::text, is_nullable::text, coalesce(column_default::text, '')
     from information_schema.columns where table_schema = 'public' and table_name = 'catalogue_items')
  ) d;
  perform pg_temp.dr_record(v_n = 0, 'S03 original catalogue_items columns (incl. price_usd, status) unchanged',
    format('%s changed column(s)', v_n));

  select count(*) into v_n from public.catalogue_items
  where listing_type is distinct from 'product' or pricing_model is distinct from 'fixed';
  perform pg_temp.dr_record(v_n = 0, 'S04 existing listings default to product + fixed price', format('%s exception(s)', v_n));

  select string_agg(coalesce(type_review_reason, '-') || ' x' || cnt, ', ') into v_txt
  from (select type_review_reason, count(*) cnt from public.catalogue_items where needs_type_review group by 1) r;
  create temp table dry_run_flagged_first as select count(*)::integer as n from public.catalogue_items where needs_type_review;
  perform pg_temp.dr_record(true, 'INFO S05 listings flagged for seller type review', coalesce(v_txt, 'none'));

  select count(*) into v_n from public.catalogue_categories
  where listing_types is distinct from array['product','service']::text[];
  perform pg_temp.dr_record(v_n = 0, 'S06 every category accepts both product and service', format('%s restricted', v_n));

  select string_agg(coalesce(suggested_listing_type, 'none') || ' x' || cnt, ', ') into v_txt
  from (select suggested_listing_type, count(*) cnt from public.catalogue_categories group by 1 order by 1) r;
  perform pg_temp.dr_record(true, 'INFO S07 category suggested type seeds', v_txt);

  select string_agg(key, ', ' order by sort_order) into v_txt
  from public.catalogue_pricing_models where checkout_compatible;
  perform pg_temp.dr_record(v_txt = 'fixed, per_unit, per_session', 'S08 checkout-compatible pricing models', v_txt);

  select * into v_pass1 from dry_run_pass1;
  perform pg_temp.dr_record(
    v_pass1.pricing_models = (select count(*) from public.catalogue_pricing_models)
    and v_pass1.units = (select count(*) from public.catalogue_units)
    and v_pass1.flagged = (select count(*) from public.catalogue_items where needs_type_review)
    and v_pass1.approvals = (select count(*) from public.catalogue_checkout_model_approvals)
    and v_pass1.policies = (select count(*) from pg_policies where schemaname = 'public' and tablename like 'catalogue\_%')
    and v_pass1.constraints = (select count(*) from pg_constraint where conrelid in ('public.catalogue_items'::regclass, 'public.catalogue_categories'::regclass))
    and v_pass1.triggers = (select count(*) from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relname like 'catalogue\_%' and not t.tgisinternal)
    and v_pass1.suggested = (select count(*) from public.catalogue_categories where suggested_listing_type is not null),
    'S09 second run changed nothing (repeatable: models, units, flags, approvals, policies, constraints, triggers)',
    format('pricing_models=%s units=%s flagged=%s approvals=%s policies=%s constraints=%s triggers=%s suggested=%s',
      v_pass1.pricing_models, v_pass1.units, v_pass1.flagged, v_pass1.approvals,
      v_pass1.policies, v_pass1.constraints, v_pass1.triggers, v_pass1.suggested));

  select count(*) into v_n from public.catalogue_items
  where status is null or status not in ('active','paused','deleted');
  perform pg_temp.dr_record(v_n = 0
    and exists (select 1 from pg_constraint where conname = 'catalogue_items_status_check'
                and conrelid = 'public.catalogue_items'::regclass and convalidated),
    'S10 status constraint present, validated, and every existing listing satisfies it',
    format('%s listing(s) outside active/paused/deleted', v_n));
end $a$;

-- ---------------------------------------------------------------------------
-- B. Published-listing rules and status values
-- ---------------------------------------------------------------------------
do $b$
declare
  v_ctx record;
  v_scope constant text := 'One 60-minute home visit including diagnosis and a written report.';
  v_terms constant text := 'Within Lagos only, booked 48 hours ahead.';
begin
  select * into v_ctx from dry_run_ctx;

  perform pg_temp.dr_expect('T01 product, fixed, $5 publishes', pg_temp.dr_insert('5', 'product', 'fixed'), true);
  perform pg_temp.dr_expect('T02 price 0 rejected', pg_temp.dr_insert('0', 'product', 'fixed'), false, 'positive USD');
  perform pg_temp.dr_expect('T03 negative price rejected', pg_temp.dr_insert('-1', 'product', 'fixed'), false, 'positive USD');
  perform pg_temp.dr_expect('T04 NaN price rejected', pg_temp.dr_insert($q$'NaN'::numeric$q$, 'product', 'fixed'), false, 'positive USD');
  perform pg_temp.dr_expect('T05 Infinity price rejected', pg_temp.dr_insert($q$'Infinity'::numeric$q$, 'product', 'fixed'), false, 'positive USD');
  perform pg_temp.dr_expect('T06 missing price rejected', pg_temp.dr_insert('null', 'product', 'fixed'), false, 'positive USD');
  perform pg_temp.dr_expect('T07 large price allowed (no arbitrary cap)', pg_temp.dr_insert('2500000', 'product', 'fixed'), true);
  perform pg_temp.dr_expect('T08 product per_unit without unit rejected', pg_temp.dr_insert('3', 'product', 'per_unit'), false, 'needs a unit');
  perform pg_temp.dr_expect('T09 product per_unit with unit publishes', pg_temp.dr_insert('3', 'product', 'per_unit', 'kg'), true);
  perform pg_temp.dr_expect('T10 product on service-only model rejected', pg_temp.dr_insert('3', 'product', 'per_session'), false, 'not available for this listing type');
  perform pg_temp.dr_expect('T11 unknown pricing model rejected', pg_temp.dr_insert('3', 'product', 'banana'), false, 'not available for this listing type');
  perform pg_temp.dr_expect('T12 quotation model cannot publish', pg_temp.dr_insert('3', 'product', 'custom_quote'), false, 'cannot be published yet');
  perform pg_temp.dr_expect('T13 hourly service cannot publish', pg_temp.dr_insert('3', 'service', 'hourly', null, v_scope, v_terms, true), false, 'cannot be published yet');
  perform pg_temp.dr_expect('T14 fixed service without scope rejected', pg_temp.dr_insert('3', 'service', 'fixed'), false, 'defined scope');
  perform pg_temp.dr_expect('T15 fixed service with scope but unconfirmed rejected', pg_temp.dr_insert('3', 'service', 'fixed', null, v_scope, v_terms, false), false, 'defined scope');
  perform pg_temp.dr_expect('T16 fixed service with confirmed scope publishes', pg_temp.dr_insert('3', 'service', 'fixed', null, v_scope, v_terms, true), true);
  perform pg_temp.dr_expect('T17 per-session service with confirmed scope publishes', pg_temp.dr_insert('3', 'service', 'per_session', null, v_scope, v_terms, true), true);
  perform pg_temp.dr_expect('T18 too-short service scope rejected', pg_temp.dr_insert('3', 'service', 'fixed', null, 'Short', v_terms, true), false, 'service_text_check');

  perform pg_temp.dr_expect('T19 category restricted to products refuses a service',
    format($q$do $x$ begin
      update public.catalogue_categories set listing_types = array['product'] where id = %L;
      %s;
    end $x$$q$, v_ctx.empty_category_id,
      pg_temp.dr_insert('3', 'service', 'per_session', null, v_scope, v_terms, true, v_ctx.empty_category_id)),
    false, 'does not accept');

  perform pg_temp.dr_expect('T20 title-only edit on existing listing runs no checks',
    format('update public.catalogue_items set title = title where id = %L', v_ctx.existing_item_id), true);
  perform pg_temp.dr_expect('T21 existing listing price set to 0 rejected',
    format('update public.catalogue_items set price_usd = 0 where id = %L', v_ctx.existing_item_id), false, 'positive USD');
  perform pg_temp.dr_expect('T22 existing listing can be paused',
    format($q$update public.catalogue_items set status = 'paused' where id = %L$q$, v_ctx.existing_item_id), true);
  perform pg_temp.dr_expect('T23 existing listing can be soft-deleted',
    format($q$update public.catalogue_items set status = 'deleted' where id = %L$q$, v_ctx.existing_item_id), true);

  -- Status values (data integrity only; says nothing about who may buy).
  perform pg_temp.dr_expect('X01 status "sold" rejected on insert', pg_temp.dr_insert('5', 'product', 'fixed', null, null, null, false, null, 'sold'), false, 'status_check');
  perform pg_temp.dr_expect('X02 null status rejected on insert', pg_temp.dr_insert('5', 'product', 'fixed', null, null, null, false, null, null), false, 'status');
  perform pg_temp.dr_expect('X03 status "paused" accepted on insert', pg_temp.dr_insert('5', 'product', 'fixed', null, null, null, false, null, 'paused'), true);
  perform pg_temp.dr_expect('X04 status "deleted" accepted on insert', pg_temp.dr_insert('5', 'product', 'fixed', null, null, null, false, null, 'deleted'), true);
  perform pg_temp.dr_expect('X05 existing listing cannot be set to an unknown status',
    format($q$update public.catalogue_items set status = 'archived' where id = %L$q$, v_ctx.existing_item_id), false, 'status_check');
  perform pg_temp.dr_expect('X06 existing listing cannot be given a null status',
    format($q$update public.catalogue_items set status = null where id = %L$q$, v_ctx.existing_item_id), false, 'status');
end $b$;

-- ---------------------------------------------------------------------------
-- C. Pricing-model approval authority
-- ---------------------------------------------------------------------------
do $c$
declare
  v_ctx record;
  v_txt text;
  v_expected_session text := session_user;
  v_expected_current text := current_user;
  v_n integer;
begin
  select * into v_ctx from dry_run_ctx;

  select count(*) into v_n from public.catalogue_pricing_models m
  where m.checkout_compatible
    and not exists (select 1 from public.catalogue_checkout_model_approvals a where a.pricing_model = m.key and a.approved_value);
  perform pg_temp.dr_record(v_n = 0, 'A01 every checkout-compatible model has an approval record (initial seeds included)',
    format('%s model(s) without a record', v_n));

  -- The database owner (the role running this script) can use the workflow.
  perform pg_temp.dr_expect('T24 direct checkout_compatible change rejected even for the owner',
    $q$update public.catalogue_pricing_models set checkout_compatible = true where key = 'hourly'$q$,
    false, 'catalogue_set_checkout_compatible');
  perform pg_temp.dr_expect('T25 owner can approve through the function',
    $q$select public.catalogue_set_checkout_compatible('hourly', true, 'DRY-RUN-TEST')$q$, true);
  perform pg_temp.dr_expect('T26 function without approval reference rejected',
    $q$select public.catalogue_set_checkout_compatible('hourly', true, '')$q$, false, 'approval reference');
  perform pg_temp.dr_expect('T26b function for an unknown model rejected',
    $q$select public.catalogue_set_checkout_compatible('no_such_model', true, 'DRY-RUN-TEST')$q$, false, 'Unknown pricing model');
  perform pg_temp.dr_expect('T27 new pricing model cannot start checkout-compatible',
    $q$insert into public.catalogue_pricing_models (key, label, applies_to, checkout_compatible) values ('dry_run_model', 'Dry run', array['product'], true)$q$,
    false, 'not checkout-compatible');
  perform pg_temp.dr_expect('T28 new (future) pricing model can be added as non-compatible',
    $q$insert into public.catalogue_pricing_models (key, label, applies_to) values ('dry_run_model', 'Dry run', array['product','service'])$q$, true);
  perform pg_temp.dr_expect('T29 approval records cannot be deleted, even by the owner',
    $q$do $x$ begin
      perform public.catalogue_set_checkout_compatible('hourly', true, 'DRY-RUN-TEST');
      delete from public.catalogue_checkout_model_approvals;
    end $x$$q$, false, 'append-only');
  perform pg_temp.dr_expect('T29b approval records cannot be updated, even by the owner',
    $q$update public.catalogue_checkout_model_approvals set approval_reference = 'edited'$q$, false, 'append-only');
  perform pg_temp.dr_expect('T29c approval records cannot be truncated, even by the owner',
    'truncate public.catalogue_checkout_model_approvals', false, 'append-only');
  perform pg_temp.dr_expect('T30 pricing model keys are permanent',
    $q$update public.catalogue_pricing_models set key = 'fixed_price' where key = 'fixed'$q$, false, 'permanent');
  perform pg_temp.dr_expect('T31 in-use pricing model cannot be deleted',
    $q$delete from public.catalogue_pricing_models where key = 'fixed'$q$, false, 'in use');
  perform pg_temp.dr_expect('T32 in-use pricing model cannot be deactivated',
    $q$update public.catalogue_pricing_models set is_active = false where key = 'fixed'$q$, false, 'published listing');
  perform pg_temp.dr_expect('T33 in-use model cannot lose checkout compatibility even with approval',
    $q$select public.catalogue_set_checkout_compatible('fixed', false, 'DRY-RUN-TEST')$q$, false, 'published listing');

  -- Identity is recorded by the database, not by the caller.
  v_txt := pg_temp.dr_probe(array[
    $q$select public.catalogue_set_checkout_compatible('hourly', true, 'DRY-RUN-IDENTITY')$q$,
    $q$select recorded_session_user || '/' || recorded_current_user from public.catalogue_checkout_model_approvals where approval_reference = 'DRY-RUN-IDENTITY'$q$]);
  perform pg_temp.dr_record(v_txt = v_expected_session || '/' || v_expected_current,
    'A02 approver identity recorded automatically by the function', v_txt);

  v_txt := pg_temp.dr_probe(array[
    $q$insert into public.catalogue_checkout_model_approvals (pricing_model, approved_value, approval_reference, recorded_session_user, recorded_current_user, created_at) values ('fixed', true, 'DRY-RUN-SPOOF', 'attacker', 'attacker', '2001-01-01')$q$,
    $q$select recorded_session_user || '/' || recorded_current_user || '/' || (created_at = now())::text from public.catalogue_checkout_model_approvals where approval_reference = 'DRY-RUN-SPOOF'$q$]);
  perform pg_temp.dr_record(v_txt = v_expected_session || '/' || v_expected_current || '/true',
    'A03 spoofed identity and timestamp in a direct insert are overwritten by the database', v_txt);

  -- Public API roles and service_role: every write path closed.
  perform pg_temp.dr_expect('P01 service_role cannot change checkout_compatible directly',
    $q$do $x$ begin set local role service_role; update public.catalogue_pricing_models set checkout_compatible = true where key = 'hourly'; end $x$$q$,
    false, 'permission denied');
  perform pg_temp.dr_expect('P02 service_role cannot insert approval records',
    $q$do $x$ begin set local role service_role; insert into public.catalogue_checkout_model_approvals (pricing_model, approved_value, approval_reference) values ('hourly', true, 'attacker'); end $x$$q$,
    false, 'permission denied');
  perform pg_temp.dr_expect('P03 service_role cannot execute the approval function',
    $q$do $x$ begin set local role service_role; perform public.catalogue_set_checkout_compatible('hourly', true, 'attacker'); end $x$$q$,
    false, 'permission denied for function');
  perform pg_temp.dr_expect('P04 service_role cannot truncate approval records',
    $q$do $x$ begin set local role service_role; truncate public.catalogue_checkout_model_approvals; end $x$$q$,
    false, 'permission denied');
  perform pg_temp.dr_expect('P05 service_role cannot delete approval records',
    $q$do $x$ begin set local role service_role; delete from public.catalogue_checkout_model_approvals; end $x$$q$,
    false, 'permission denied');
  perform pg_temp.dr_expect('P06 service_role cannot add pricing models',
    $q$do $x$ begin set local role service_role; insert into public.catalogue_pricing_models (key, label, applies_to) values ('attacker_model', 'x', array['product']); end $x$$q$,
    false, 'permission denied');
  perform pg_temp.dr_expect('P07 service_role cannot truncate pricing models',
    $q$do $x$ begin set local role service_role; truncate public.catalogue_pricing_models; end $x$$q$,
    false, 'permission denied');
  perform pg_temp.dr_expect('P08 service_role cannot read approval records',
    $q$do $x$ begin set local role service_role; perform count(*) from public.catalogue_checkout_model_approvals; end $x$$q$,
    false, 'permission denied');
  perform pg_temp.dr_expect('P09 authenticated cannot execute the approval function',
    $q$do $x$ begin set local role authenticated; perform public.catalogue_set_checkout_compatible('hourly', true, 'attacker'); end $x$$q$,
    false, 'permission denied for function');
  perform pg_temp.dr_expect('P10 anon cannot execute the approval function',
    $q$do $x$ begin set local role anon; perform public.catalogue_set_checkout_compatible('hourly', true, 'attacker'); end $x$$q$,
    false, 'permission denied for function');
  perform pg_temp.dr_expect('P11 anon cannot update pricing models',
    $q$do $x$ begin set local role anon; update public.catalogue_pricing_models set checkout_compatible = true where key = 'hourly'; end $x$$q$,
    false, 'permission denied');
  perform pg_temp.dr_expect('P12 authenticated cannot insert approval records',
    $q$do $x$ begin set local role authenticated; insert into public.catalogue_checkout_model_approvals (pricing_model, approved_value, approval_reference) values ('hourly', true, 'attacker'); end $x$$q$,
    false, 'permission denied');
  perform pg_temp.dr_expect('P13 defence in depth: even if EXECUTE were granted to service_role by mistake, the function refuses',
    $q$do $x$ begin
      grant execute on function public.catalogue_set_checkout_compatible(text, boolean, text) to service_role;
      set local role service_role;
      perform public.catalogue_set_checkout_compatible('hourly', true, 'attacker');
    end $x$$q$,
    false, 'Only the database owner');

  -- service_role keeps what the listings API needs.
  perform pg_temp.dr_expect('P14 service_role can still publish a valid listing (API path)',
    format($q$do $x$ begin set local role service_role; %s; end $x$$q$, pg_temp.dr_insert('5', 'product', 'fixed')), true);
  perform pg_temp.dr_expect('P15 service_role can still reject an invalid listing price (rules apply to every role)',
    format($q$do $x$ begin set local role service_role; %s; end $x$$q$, pg_temp.dr_insert('0', 'product', 'fixed')), false, 'positive USD');
  perform pg_temp.dr_expect('P16 service_role can write drafts, details and attributes, and read pricing models',
    format($q$do $x$ begin
      set local role service_role;
      insert into public.catalogue_listing_drafts (seller_username, listing_type, title, pricing_model) values ('dry_run_seller', 'service', 'Dry run quote', 'custom_quote');
      insert into public.catalogue_product_details (item_id, brand) values (%L, 'Dry run');
      insert into public.catalogue_item_attributes (item_id, custom_label, value) values (%L, 'Finish', '"matte"'::jsonb);
      perform count(*) from public.catalogue_pricing_models;
      perform count(*) from public.catalogue_units;
    end $x$$q$, v_ctx.existing_item_id, v_ctx.existing_item_id), true);
end $c$;

-- ---------------------------------------------------------------------------
-- D. Categories, drafts, attributes, draft-to-listing ownership
-- ---------------------------------------------------------------------------
do $d$
declare
  v_ctx record;
begin
  select * into v_ctx from dry_run_ctx;

  perform pg_temp.dr_expect('T34 narrowing a category that would strand listings rejected',
    $q$update public.catalogue_categories set listing_types = array['service'] where slug = 'other'$q$,
    false, 'would no longer accept');
  perform pg_temp.dr_expect('T35 narrowing an empty category accepted',
    format($q$update public.catalogue_categories set listing_types = array['service'] where id = %L$q$, v_ctx.empty_category_id), true);

  perform pg_temp.dr_expect('T36 quotation draft without price saved',
    $q$insert into public.catalogue_listing_drafts (seller_username, listing_type, title, pricing_model) values ('dry_run_seller', 'service', 'Dry run quote', 'custom_quote')$q$, true);
  perform pg_temp.dr_expect('T37 draft with zero price rejected',
    $q$insert into public.catalogue_listing_drafts (seller_username, listing_type, title, pricing_model, price_usd) values ('dry_run_seller', 'product', 'Dry run', 'fixed', 0)$q$,
    false, 'check constraint');
  perform pg_temp.dr_expect('T38 draft with stock, min order and price range saved',
    $q$insert into public.catalogue_listing_drafts (seller_username, listing_type, title, pricing_model, price_usd, price_max_usd, min_order_qty, stock_status, stock_quantity) values ('dry_run_seller', 'product', 'Dry run', 'per_unit', 2, 5, 10, 'limited', 40)$q$, true);
  perform pg_temp.dr_expect('T39 seller-defined (Other / Specify) attribute saved',
    format($q$insert into public.catalogue_item_attributes (item_id, custom_label, value) values (%L, 'Finish', '"matte"'::jsonb)$q$, v_ctx.existing_item_id), true);
  perform pg_temp.dr_expect('T40 attribute with neither definition nor label rejected',
    format($q$insert into public.catalogue_item_attributes (item_id, value) values (%L, '"x"'::jsonb)$q$, v_ctx.existing_item_id),
    false, 'check constraint');

  -- Draft ownership
  perform pg_temp.dr_expect('D01 draft linked to a listing of the same seller accepted',
    format($q$insert into public.catalogue_listing_drafts (seller_username, listing_type, title, pricing_model, published_item_id) values (%L, 'product', 'Dry run', 'fixed', %L)$q$, v_ctx.existing_seller, v_ctx.existing_item_id), true);
  perform pg_temp.dr_expect('D02 draft linked to another seller''s listing rejected',
    format($q$insert into public.catalogue_listing_drafts (seller_username, listing_type, title, pricing_model, published_item_id) values ('dry_run_other_seller', 'product', 'Dry run', 'fixed', %L)$q$, v_ctx.existing_item_id),
    false, 'same seller');
  perform pg_temp.dr_expect('D03 draft linked to a non-existent listing rejected',
    format($q$insert into public.catalogue_listing_drafts (seller_username, listing_type, title, pricing_model, published_item_id) values (%L, 'product', 'Dry run', 'fixed', gen_random_uuid())$q$, v_ctx.existing_seller),
    false, 'does not exist');
  perform pg_temp.dr_expect('D04 changing a linked draft''s seller rejected',
    format($q$do $x$ begin
      insert into public.catalogue_listing_drafts (seller_username, listing_type, title, pricing_model, published_item_id) values (%L, 'product', 'Dry run', 'fixed', %L);
      update public.catalogue_listing_drafts set seller_username = 'dry_run_other_seller' where published_item_id = %L;
    end $x$$q$, v_ctx.existing_seller, v_ctx.existing_item_id, v_ctx.existing_item_id),
    false, 'same seller');
  perform pg_temp.dr_expect('D05 changing a listing''s seller while a draft is linked rejected',
    format($q$do $x$ begin
      insert into public.catalogue_listing_drafts (seller_username, listing_type, title, pricing_model, published_item_id) values (%L, 'product', 'Dry run', 'fixed', %L);
      update public.catalogue_items set seller_username = 'dry_run_other_seller' where id = %L;
    end $x$$q$, v_ctx.existing_seller, v_ctx.existing_item_id, v_ctx.existing_item_id),
    false, 'linked draft');
  perform pg_temp.dr_expect('D06 changing a listing''s seller with no linked draft accepted',
    format($q$update public.catalogue_items set seller_username = 'dry_run_other_seller' where id = %L$q$, v_ctx.existing_item_id), true);
  perform pg_temp.dr_expect('D07 re-linking an unlinked draft to another seller''s listing rejected',
    format($q$do $x$ begin
      insert into public.catalogue_listing_drafts (seller_username, listing_type, title, pricing_model) values ('dry_run_seller', 'product', 'Dry run', 'fixed');
      update public.catalogue_listing_drafts set published_item_id = %L where seller_username = 'dry_run_seller';
    end $x$$q$, v_ctx.existing_item_id),
    false, 'same seller');
  perform pg_temp.dr_expect('D08 the ownership rule also binds service_role',
    format($q$do $x$ begin
      insert into public.catalogue_listing_drafts (seller_username, listing_type, title, pricing_model, published_item_id) values (%L, 'product', 'Dry run', 'fixed', %L);
      set local role service_role;
      update public.catalogue_items set seller_username = 'dry_run_other_seller' where id = %L;
    end $x$$q$, v_ctx.existing_seller, v_ctx.existing_item_id, v_ctx.existing_item_id),
    false, 'linked draft');
end $d$;

-- ---------------------------------------------------------------------------
-- E. Public visibility: details follow the listing's own visibility
-- ---------------------------------------------------------------------------
do $e$
declare
  v_ctx record;
  v_active text;
  v_paused text;
  v_deleted text;
  v_policies text;
begin
  select * into v_ctx from dry_run_ctx;

  v_active := pg_temp.dr_probe(array[
    format($q$insert into public.catalogue_product_details (item_id, brand) values (%L, 'Dry run brand')$q$, v_ctx.existing_item_id),
    'set local role anon',
    format($q$select (select count(*) from public.catalogue_items where id = %L)::text || '/' || (select count(*) from public.catalogue_product_details where item_id = %L)::text$q$, v_ctx.existing_item_id, v_ctx.existing_item_id)]);
  v_paused := pg_temp.dr_probe(array[
    format($q$insert into public.catalogue_product_details (item_id, brand) values (%L, 'Dry run brand')$q$, v_ctx.existing_item_id),
    format($q$update public.catalogue_items set status = 'paused' where id = %L$q$, v_ctx.existing_item_id),
    'set local role anon',
    format($q$select (select count(*) from public.catalogue_items where id = %L)::text || '/' || (select count(*) from public.catalogue_product_details where item_id = %L)::text$q$, v_ctx.existing_item_id, v_ctx.existing_item_id)]);
  v_deleted := pg_temp.dr_probe(array[
    format($q$insert into public.catalogue_product_details (item_id, brand) values (%L, 'Dry run brand')$q$, v_ctx.existing_item_id),
    format($q$update public.catalogue_items set status = 'deleted' where id = %L$q$, v_ctx.existing_item_id),
    'set local role anon',
    format($q$select (select count(*) from public.catalogue_items where id = %L)::text || '/' || (select count(*) from public.catalogue_product_details where item_id = %L)::text$q$, v_ctx.existing_item_id, v_ctx.existing_item_id)]);

  perform pg_temp.dr_record(v_active = '1/1', 'V01 anon, active listing: listing and its details both visible (listing/details rows)', v_active);
  perform pg_temp.dr_record(v_paused = '1/1', 'V02 anon, paused listing: listing and its details both visible, matching the existing listing read rule', v_paused);
  perform pg_temp.dr_record(v_deleted = '0/0', 'V03 anon, deleted listing: neither listing nor details visible', v_deleted);

  select string_agg(policyname || ' (' || cmd || ')', ', ') into v_policies
  from pg_policies where schemaname = 'public' and tablename = 'catalogue_items';
  perform pg_temp.dr_record(v_policies = 'public read active items (SELECT)',
    'V04 catalogue_items policies unchanged (single read policy, no write policy)', v_policies);

  perform pg_temp.dr_expect('V05 anon cannot read drafts',
    $q$do $x$ begin set local role anon; perform count(*) from public.catalogue_listing_drafts; end $x$$q$, false, 'permission denied');
  perform pg_temp.dr_expect('V06 authenticated cannot read or write drafts',
    $q$do $x$ begin set local role authenticated; insert into public.catalogue_listing_drafts (seller_username, listing_type, title, pricing_model) values ('x', 'product', 'x', 'fixed'); end $x$$q$,
    false, 'permission denied');
  perform pg_temp.dr_expect('V07 anon can read pricing models',
    $q$do $x$ begin set local role anon; perform count(*) from public.catalogue_pricing_models; end $x$$q$, true);
  perform pg_temp.dr_expect('V08 anon cannot insert listings (lockdown intact)',
    format($q$do $x$ begin set local role anon; %s; end $x$$q$, pg_temp.dr_insert('5', 'product', 'fixed')),
    false, 'permission denied');
end $e$;

-- ---------------------------------------------------------------------------
-- F. Functions exposed to the API, and effective privileges
-- ---------------------------------------------------------------------------
do $f$
declare
  v_ctx record;
  v_tbl text;
  v_role text;
  v_priv text;
  v_txt text;
  v_bad text;
  v_roles text[];
  v_fn record;
begin
  select * into v_ctx from dry_run_ctx;
  v_roles := array['anon', 'authenticated', 'service_role', v_ctx.owner_role];

  -- Functions added by the migration
  select string_agg(
           format('%s(%s) %s search_path=%s',
             p.proname, pg_get_function_identity_arguments(p.oid),
             case when p.prosecdef then 'SECURITY DEFINER' else 'SECURITY INVOKER' end,
             coalesce((select c from unnest(p.proconfig) c where c like 'search_path=%'), 'UNSET')),
           E'\n           ' order by p.proname)
  into v_txt
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public' and p.prokind in ('f','p')
    and (p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')') not in (select name from dry_run_objects_before where kind = 'function');
  perform pg_temp.dr_record(true, 'INFO F00 functions added by the migration', E'\n           ' || v_txt);

  select string_agg(p.proname || ' executable by ' ||
           coalesce(nullif(concat_ws(', ',
             case when exists (select 1 from aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a where a.grantee = 0 and a.privilege_type = 'EXECUTE') then 'PUBLIC' end,
             case when has_function_privilege('anon', p.oid, 'EXECUTE') then 'anon' end,
             case when has_function_privilege('authenticated', p.oid, 'EXECUTE') then 'authenticated' end,
             case when has_function_privilege('service_role', p.oid, 'EXECUTE') then 'service_role' end), ''), 'nobody'),
           '; ')
  into v_bad
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public' and p.prokind in ('f','p')
    and (p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')') not in (select name from dry_run_objects_before where kind = 'function')
    and (exists (select 1 from aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a where a.grantee = 0 and a.privilege_type = 'EXECUTE')
         or has_function_privilege('anon', p.oid, 'EXECUTE')
         or has_function_privilege('authenticated', p.oid, 'EXECUTE')
         or has_function_privilege('service_role', p.oid, 'EXECUTE'));
  perform pg_temp.dr_record(v_bad is null, 'F01 no new function can be executed (or called as an API RPC) by PUBLIC, anon, authenticated or service_role',
    coalesce('EXPOSED: ' || v_bad, 'ok'));

  select string_agg(p.proname, ', ') into v_bad
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public' and p.prosecdef
    and (p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')') not in (select name from dry_run_objects_before where kind = 'function')
    and not exists (select 1 from unnest(coalesce(p.proconfig, '{}'::text[])) c where c like 'search_path=%');
  perform pg_temp.dr_record(v_bad is null, 'F02 every new SECURITY DEFINER function pins its search_path', coalesce('UNPINNED: ' || v_bad, 'ok'));

  perform pg_temp.dr_record(
    exists (select 1 from pg_proc where oid = 'public.catalogue_set_checkout_compatible(text, boolean, text)'::regprocedure and not prosecdef),
    'F03 the approval function is SECURITY INVOKER (cannot lend its owner''s privileges)', null);

  perform pg_temp.dr_record(
    has_function_privilege(v_ctx.owner_role, 'public.catalogue_set_checkout_compatible(text, boolean, text)'::regprocedure, 'EXECUTE'),
    'F04 the database owner role (' || v_ctx.owner_role || ') can execute the approval function', null);

  -- Effective table privileges
  foreach v_tbl in array array['catalogue_pricing_models', 'catalogue_checkout_model_approvals', 'catalogue_units', 'catalogue_attribute_definitions', 'catalogue_product_details', 'catalogue_service_details', 'catalogue_item_attributes', 'catalogue_listing_drafts'] loop
    v_txt := null;
    foreach v_role in array v_roles loop
      v_priv := coalesce((select string_agg(p, ',') from unnest(array['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p
                          where has_table_privilege(v_role, 'public.' || v_tbl, p)), 'none');
      v_txt := coalesce(v_txt || E'\n           ', '') || rpad(v_role, 14) || v_priv;
    end loop;
    perform pg_temp.dr_record(true, 'INFO effective privileges on ' || v_tbl, E'\n           ' || v_txt);
  end loop;

  foreach v_tbl in array array['catalogue_pricing_models', 'catalogue_checkout_model_approvals', 'catalogue_units', 'catalogue_attribute_definitions', 'catalogue_product_details', 'catalogue_service_details', 'catalogue_item_attributes', 'catalogue_listing_drafts'] loop
    foreach v_role in array array['anon','authenticated'] loop
      v_txt := null;
      foreach v_priv in array array['INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] loop
        if has_table_privilege(v_role, 'public.' || v_tbl, v_priv) then
          v_txt := coalesce(v_txt || ',', '') || v_priv;
        end if;
      end loop;
      perform pg_temp.dr_record(v_txt is null, format('G %s: %s has no write privileges', v_tbl, v_role), coalesce('HAS ' || v_txt, 'ok'));
    end loop;
  end loop;

  perform pg_temp.dr_record(
    not exists (select 1 from unnest(array['catalogue_listing_drafts','catalogue_checkout_model_approvals']) t
                where has_table_privilege('anon', 'public.' || t, 'SELECT') or has_table_privilege('authenticated', 'public.' || t, 'SELECT')),
    'G01 drafts and approval records are not readable by anon or authenticated', null);

  select string_agg(c.relname, ', ') into v_bad
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and not c.relrowsecurity and c.relname = any(array['catalogue_pricing_models', 'catalogue_checkout_model_approvals', 'catalogue_units', 'catalogue_attribute_definitions', 'catalogue_product_details', 'catalogue_service_details', 'catalogue_item_attributes', 'catalogue_listing_drafts']);
  perform pg_temp.dr_record(v_bad is null, 'G02 row-level security enabled on all new tables', coalesce('MISSING: ' || v_bad, 'ok'));

  select string_agg(p, ', ') into v_bad from unnest(array['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p
  where has_table_privilege('service_role', 'public.catalogue_checkout_model_approvals', p);
  perform pg_temp.dr_record(v_bad is null, 'G03 service_role has no privilege at all on approval records', coalesce('HAS: ' || v_bad, 'ok'));

  select string_agg(p, ', ') into v_bad from unnest(array['INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p
  where has_table_privilege('service_role', 'public.catalogue_pricing_models', p);
  perform pg_temp.dr_record(v_bad is null and has_table_privilege('service_role', 'public.catalogue_pricing_models', 'SELECT'),
    'G04 service_role can only read pricing models', coalesce('HAS: ' || v_bad, 'ok'));

  select string_agg(t || ':' || p, ', ') into v_bad
  from unnest(array['catalogue_units','catalogue_attribute_definitions','catalogue_product_details','catalogue_service_details','catalogue_item_attributes','catalogue_listing_drafts']) t,
       unnest(array['TRUNCATE','REFERENCES','TRIGGER']) p
  where has_table_privilege('service_role', 'public.' || t, p);
  perform pg_temp.dr_record(v_bad is null, 'G05 service_role has no TRUNCATE/REFERENCES/TRIGGER on the new data tables', coalesce('HAS: ' || v_bad, 'ok'));

  perform pg_temp.dr_record(
    not exists (select 1 from unnest(array['anon','authenticated','service_role']) r
                where has_sequence_privilege(r, 'public.catalogue_checkout_model_approvals_id_seq', 'USAGE')
                   or has_sequence_privilege(r, 'public.catalogue_checkout_model_approvals_id_seq', 'UPDATE')),
    'G06 no API role can use the approvals sequence', null);
end $f$;

-- ---------------------------------------------------------------------------
-- Dry run: object diff (payment boundary)
-- ---------------------------------------------------------------------------
do $diff$
declare
  v_new_tables constant text[] := array['catalogue_pricing_models', 'catalogue_checkout_model_approvals', 'catalogue_units', 'catalogue_attribute_definitions', 'catalogue_product_details', 'catalogue_service_details', 'catalogue_item_attributes', 'catalogue_listing_drafts'];
  v_expected constant text[] := array[
    'table|catalogue_items', 'table|catalogue_categories',
    'trigger|catalogue_items.catalogue_items_enforce_listing_rules',
    'trigger|catalogue_items.catalogue_items_seller_change_guard',
    'trigger|catalogue_categories.catalogue_categories_listing_types_guard',
    'constraint|catalogue_items.catalogue_items_status_check',
    'constraint|catalogue_items.catalogue_items_listing_type_check',
    'constraint|catalogue_items.catalogue_items_pricing_model_fkey',
    'constraint|catalogue_items.catalogue_items_price_unit_check',
    'constraint|catalogue_items.catalogue_items_service_text_check',
    'constraint|catalogue_categories.catalogue_categories_listing_types_check',
    'constraint|catalogue_categories.catalogue_categories_suggested_listing_type_check',
    'index|catalogue_items.catalogue_items_listing_type_idx',
    'index|catalogue_items.catalogue_items_pricing_model_idx',
    'index|catalogue_items.catalogue_items_needs_type_review_idx',
    'function|catalogue_checkout_approvals_set_identity()',
    'function|catalogue_checkout_approvals_append_only()',
    'function|catalogue_pricing_models_guard()',
    'function|catalogue_set_checkout_compatible(p_key text, p_value boolean, p_approval_reference text)',
    'function|catalogue_items_enforce_listing_rules()',
    'function|catalogue_categories_listing_types_guard()',
    'function|catalogue_listing_drafts_owner_guard()',
    'function|catalogue_items_seller_change_guard()'];
  v_changed text;
  v_unexpected text;
begin
  with after_objs as (select * from pg_temp.dr_objects()),
  diff as (
    select coalesce(a.kind, b.kind) as kind, coalesce(a.name, b.name) as name,
           case when b.name is null then 'added' when a.name is null then 'removed' else 'changed' end as change
    from after_objs a
    full join dry_run_objects_before b on b.kind = a.kind and b.name = a.name
    where a.sig is distinct from b.sig
  )
  select
    string_agg(kind || ' ' || name || ' ' || change, E'\n           ' order by kind, name),
    string_agg(kind || ' ' || name || ' ' || change, E'\n           ' order by kind, name) filter (where not (
      (kind || '|' || name) = any(v_expected)
      or (kind in ('trigger','policy','grant','constraint','index','table')
          and split_part(split_part(name, '.', 1), '->', 1) = any(v_new_tables))
    ))
  into v_changed, v_unexpected
  from diff;

  perform pg_temp.dr_record(v_unexpected is null,
    'B01 nothing outside the listing engine changed (payments, orders, wallets, existing grants, policies, triggers, functions, indexes, constraints)',
    coalesce('UNEXPECTED: ' || v_unexpected, 'ok'));
  perform pg_temp.dr_record(true, 'INFO B objects added or changed by the migration', E'\n           ' || coalesce(v_changed, 'none'));
end $diff$;

