-- ---------------------------------------------------------------------------
-- Dry run: after rollback run 1 - database equals snapshot, archive complete
-- ---------------------------------------------------------------------------
create temp table dry_run_archive_run as
select run_id, source_counts from catalogue_engine_archive.runs where verified and source_counts ->> 'catalogue_listing_drafts' is not null;

do $rb$
declare
  v_diff text;
  v_n integer;
  v_run uuid;
  v_expected jsonb;
  v_actual jsonb;
  v_txt text;
  v_role text;
begin
  with after_objs as (select * from pg_temp.dr_objects())
  select string_agg(coalesce(a.kind, b.kind) || ' ' || coalesce(a.name, b.name) ||
           case when b.name is null then ' left behind' when a.name is null then ' missing' else ' differs' end,
           '; ' order by coalesce(a.kind, b.kind), coalesce(a.name, b.name))
  into v_diff
  from after_objs a
  full join dry_run_objects_before b on b.kind = a.kind and b.name = a.name
  where a.sig is distinct from b.sig;
  perform pg_temp.dr_record(v_diff is null, 'R01 rollback restores every public object (tables, triggers, policies, constraints, indexes, functions, grants) to the pre-migration state',
    coalesce('DIFFERENCES: ' || v_diff, 'ok'));

  select count(*) into v_n from (
    (select * from dry_run_items_before
     except
     select id, seller_username, title, description, price_usd, images, payment_methods,
            status, created_at, updated_at, size, promo_video_url, category_id
     from public.catalogue_items)
    union all
    (select id, seller_username, title, description, price_usd, images, payment_methods,
            status, created_at, updated_at, size, promo_video_url, category_id
     from public.catalogue_items
     except
     select * from dry_run_items_before)
  ) d;
  perform pg_temp.dr_record(v_n = 0, 'R02 listings intact after rollback', format('%s differing row(s)', v_n));

  select count(*) into v_n from dry_run_archive_run;
  perform pg_temp.dr_record(v_n = 1, 'R03 exactly one verified archive run holds the engine data', format('%s run(s)', v_n));

  select run_id, source_counts into v_run, v_actual from dry_run_archive_run limit 1;
  select expected_counts into v_expected from dry_run_pre_rollback;
  perform pg_temp.dr_record(v_actual = v_expected, 'R04 archived row counts equal the live row counts before the drop (drafts, details, attributes, definitions, pricing config, approvals, listing classification, category types)',
    format('archived=%s expected=%s', v_actual, v_expected));

  select count(*) into v_n from catalogue_engine_archive.archived_rows
  where run_id = v_run and source = 'catalogue_listing_drafts' and row_data ->> 'title' = 'Dry run archived draft'
    and row_data ->> 'stock_status' = 'limited';
  perform pg_temp.dr_record(v_n = 1, 'R05 archived draft content is intact', format('%s match(es)', v_n));

  select count(*) into v_n from catalogue_engine_archive.archived_rows
  where run_id = v_run and source = 'catalogue_pricing_models' and source_key = 'hourly'
    and (row_data ->> 'checkout_compatible')::boolean;
  perform pg_temp.dr_record(v_n = 1, 'R06 archived pricing configuration includes the approved model', format('%s match(es)', v_n));

  select count(*) into v_n from catalogue_engine_archive.archived_rows
  where run_id = v_run and source = 'catalogue_checkout_model_approvals'
    and row_data ->> 'approval_reference' = 'DRY-RUN-ARCHIVE-TEST'
    and row_data ->> 'recorded_current_user' = current_user;
  perform pg_temp.dr_record(v_n = 1, 'R07 archived approval records keep the recorded approver identity', format('%s match(es)', v_n));

  select count(*) into v_n from catalogue_engine_archive.archived_rows
  where run_id = v_run and source = 'catalogue_items.classification'
    and source_key = (select existing_item_id::text from dry_run_ctx)
    and row_data ->> 'listing_type' = 'product';
  perform pg_temp.dr_record(v_n = 1, 'R08 archived listing classification present for an existing listing', format('%s match(es)', v_n));

  v_txt := null;
  foreach v_role in array array['anon','authenticated','service_role'] loop
    if has_schema_privilege(v_role, 'catalogue_engine_archive', 'USAGE')
       or has_table_privilege(v_role, 'catalogue_engine_archive.archived_rows', 'SELECT')
       or has_table_privilege(v_role, 'catalogue_engine_archive.runs', 'SELECT') then
      v_txt := coalesce(v_txt || ', ', '') || v_role;
    end if;
  end loop;
  perform pg_temp.dr_record(v_txt is null, 'R09 archive schema is not reachable by anon, authenticated or service_role (no schema usage, no table access)',
    coalesce('REACHABLE BY: ' || v_txt, 'ok'));

  perform pg_temp.dr_expect('R10 service_role cannot read the archive',
    $q$do $x$ begin set local role service_role; perform count(*) from catalogue_engine_archive.archived_rows; end $x$$q$, false, 'permission denied');
  perform pg_temp.dr_expect('R11 authenticated cannot read the archive',
    $q$do $x$ begin set local role authenticated; perform count(*) from catalogue_engine_archive.runs; end $x$$q$, false, 'permission denied');

  perform pg_temp.dr_record(
    (select bool_and(c.relrowsecurity) from pg_class c where c.oid in ('catalogue_engine_archive.runs'::regclass, 'catalogue_engine_archive.archived_rows'::regclass)),
    'R12 archive tables have row-level security enabled', null);

  select count(*) into v_n from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relname = any(array['catalogue_pricing_models', 'catalogue_checkout_model_approvals', 'catalogue_units', 'catalogue_attribute_definitions', 'catalogue_product_details', 'catalogue_service_details', 'catalogue_item_attributes', 'catalogue_listing_drafts']);
  perform pg_temp.dr_record(v_n = 0, 'R13 all engine tables are gone from public', format('%s remaining', v_n));
end $rb$;

